<script setup lang="ts">
/**
 * Inline status callout (`design/components/alert.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/alert.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onBeforeUnmount, onMounted, ref, useTemplateRef } from 'vue'

import { Icon, agentMember, useDeparture, useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/alert.module.css'
import Button from '../controls/Button.vue'

export type AlertTone = NonNullable<AlertProps['tone']>

export interface AlertProps {
  /**
   * The ✕'s accessible name, default `Dismiss`; localized hosts pass their own.
   */
  dismissLabel?: string
  /**
   * `false` hides the tone glyph, for dense stacks where the wash already shows the tone.
   */
  icon?: false
  /**
   * The first line. An empty title counts as no title.
   */
  title?: string
  tone?: 'info' | 'warning' | 'success' | 'danger'
}

defineOptions({ name: 'Alert', inheritAttrs: false })

const props = withDefaults(defineProps<AlertProps>(), {
  dismissLabel: 'Dismiss',
  icon: undefined,
  tone: 'info',
})
const emit = defineEmits<{ dismiss: [] }>()
defineSlots<{
  action?: (props: Record<string, never>) => unknown
  default?: (props: Record<string, never>) => unknown
  secondaryAction?: (props: Record<string, never>) => unknown
}>()
const listening = useListening()
const settle = ref(undefined as (() => void) | undefined)
const closeRegion = useTemplateRef<HTMLElement>('closeRegion')
const root = useTemplateRef<HTMLElement>('root')
const departure = useDeparture(root, 'alert.dismiss')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  undefined
  release1 = () => {
    settle.value?.()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Alert',
    element: () => root.value,
    state: () => ({ tone: props.tone, title: props.title ?? '', dismissible: listening.dismiss }),
    actions: {
      dismiss: () =>
        (() => {
          if (!listening.dismiss) throw new Error('This alert has no dismiss control.')
          return new Promise<void>((resolve) => {
            settle.value = () => {
              settle.value = undefined
              resolve()
            }
            departure.start(() => {
              emit('dismiss')
              settle.value?.()
            })
          })
        })(),
    },
    withholds: () => closeRegion.value,
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div
    v-if="(title !== undefined && title !== '') || $slots.default"
    ref="root"
    :class="styles.alert"
    :role="tone === 'warning' || tone === 'danger' ? 'alert' : 'status'"
    :data-tone="tone"
    :data-state="departure.active ? 'closed' : undefined"
    data-member="alert"
  >
    <!-- panel -->
    <div :class="styles.panel">
      <!-- glyph -->
      <span v-if="icon !== false" :class="styles.glyph">
        <Icon :name="tone === 'danger' ? 'error' : tone" />
      </span>
      <!-- body -->
      <div :class="styles.body">
        <!-- title -->
        <p v-if="title !== undefined && title !== ''" :class="styles.title">
          {{ title }}
        </p>
        <!-- text -->
        <div v-if="$slots.default" :class="styles.text">
          <slot />
        </div>
        <!-- actions -->
        <div v-if="$slots.action || $slots.secondaryAction" :class="styles.action">
          <slot name="action" />
          <slot name="secondaryAction" />
        </div>
      </div>
      <!-- close -->
      <div v-if="listening.dismiss" ref="closeRegion" :class="styles.close">
        <Button
          variant="ghost"
          tone="neutral"
          size="sm"
          :iconOnly="true"
          icon="close"
          :label="dismissLabel"
          @click="
            departure.start(() => {
              emit('dismiss')
              settle?.()
            })
          "
        />
      </div>
    </div>
  </div>
</template>
